"use client";

import { useMemo, useState } from "react";
import { motion } from "motion/react";

const rows = [
  { id: "1", name: "Olivia Martin", status: "Active", amount: 1999 },
  { id: "2", name: "Jackson Lee", status: "Invited", amount: 39 },
  { id: "3", name: "Isabella Nguyen", status: "Active", amount: 299 },
  { id: "4", name: "William Kim", status: "Suspended", amount: 99 },
  { id: "5", name: "Sofia Davis", status: "Active", amount: 4250 },
];
type Key = "name" | "status" | "amount";

export function DataTableTailwind() {
  const [sort, setSort] = useState<{ key: Key; asc: boolean } | null>(null);
  const [sel, setSel] = useState<string[]>([]);
  const data = useMemo(() => !sort ? rows : [...rows].sort((a, b) => (a[sort.key] > b[sort.key] ? 1 : -1) * (sort.asc ? 1 : -1)), [sort]);
  const th = (key: Key, label: string) => (
    <th scope="col" aria-sort={sort?.key === key ? (sort.asc ? "ascending" : "descending") : "none"} className="h-10 px-4 text-left text-xs font-medium text-zinc-400">
      <button type="button" onClick={() => setSort({ key, asc: sort?.key === key ? !sort.asc : true })} className="-ml-2 rounded-md px-2 py-1 hover:bg-zinc-800 hover:text-zinc-100">{label} {sort?.key === key ? (sort.asc ? "↑" : "↓") : "↕"}</button>
    </th>
  );
  return (
    <div className="w-full max-w-2xl overflow-hidden rounded-xl border border-zinc-800 bg-zinc-900 text-sm text-zinc-100">
      <table className="w-full">
        <caption className="px-4 py-3 text-left font-semibold">Recent customers</caption>
        <thead className="border-b border-zinc-800"><tr>
          <th className="w-10 pl-4"><input type="checkbox" aria-label="Select all" className="accent-indigo-500" checked={sel.length === rows.length} onChange={() => setSel(sel.length === rows.length ? [] : rows.map((r) => r.id))} /></th>
          {th("name", "Customer")}{th("status", "Status")}{th("amount", "Amount")}
        </tr></thead>
        <tbody>
          {data.map((r) => (
            <motion.tr layout key={r.id} className={`border-b border-zinc-800 last:border-0 hover:bg-zinc-800/60 ${sel.includes(r.id) ? "bg-indigo-500/10" : ""}`}>
              <td className="pl-4"><input type="checkbox" aria-label={`Select ${r.name}`} className="accent-indigo-500" checked={sel.includes(r.id)} onChange={() => setSel(sel.includes(r.id) ? sel.filter((x) => x !== r.id) : [...sel, r.id])} /></td>
              <td className="h-12 px-4 font-medium">{r.name}</td>
              <td className="px-4 text-zinc-400">{r.status}</td>
              <td className="px-4 tabular-nums">${r.amount.toLocaleString("en-US")}</td>
            </motion.tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
